use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Iterates through the AST, extracts individual declarations, and writes them to separate files."] # [doc = " Returns a vector of Identifiers for the collected module names and a line count report."] pub fn extract_and_write_declarations (syntax_tree : & syn :: File , paths : & CratePaths , config : & SplitDeclsConfig , dry_run : bool , common_uses : TokenStream ,) -> Result < (Vec < Ident > , LineCountReport) > { let mut collected_module_names : Vec < Ident > = Vec :: new () ; let mut item_count = 0 ; let mut report = LineCountReport :: new () ; let input_content = std :: fs :: read_to_string (& paths . old_lib_rs_path) ? ; report . add_input_lines (count_lines_in_string (& input_content)) ; for item in & syntax_tree . items { let extracted_decl = match item { Item :: Fn (item_fn) => Some (ExtractedDecl { name : item_fn . sig . ident . to_string () , kind : "fn" . to_string () , content : item_fn . to_token_stream () , }) , Item :: Struct (item_struct) => Some (ExtractedDecl { name : item_struct . ident . to_string () , kind : "struct" . to_string () , content : item_struct . to_token_stream () , }) , Item :: Enum (item_enum) => Some (ExtractedDecl { name : item_enum . ident . to_string () , kind : "enum" . to_string () , content : item_enum . to_token_stream () , }) , Item :: Const (item_const) => Some (ExtractedDecl { name : item_const . ident . to_string () , kind : "const" . to_string () , content : item_const . to_token_stream () , }) , Item :: Static (item_static) => Some (ExtractedDecl { name : item_static . ident . to_string () , kind : "static" . to_string () , content : item_static . to_token_stream () , }) , Item :: Trait (item_trait) => Some (ExtractedDecl { name : item_trait . ident . to_string () , kind : "trait" . to_string () , content : item_trait . to_token_stream () , }) , Item :: Impl (item_impl) => { let name = if let Some ((_ , path , _)) = & item_impl . trait_ { format ! ("impl_for_{}" , path . to_token_stream () . to_string () . replace ("::" , "_")) } else if let syn :: Type :: Path (type_path) = & * item_impl . self_ty { if let Some (segment) = type_path . path . segments . last () { format ! ("impl_for_{}" , segment . ident . to_string ()) } else { format ! ("impl_{}" , item_count) } } else { format ! ("impl_{}" , item_count) } ; Some (ExtractedDecl { name , kind : "impl" . to_string () , content : item_impl . to_token_stream () , }) } , Item :: Type (item_type) => Some (ExtractedDecl { name : item_type . ident . to_string () , kind : "type" . to_string () , content : item_type . to_token_stream () , }) , Item :: Union (item_union) => Some (ExtractedDecl { name : item_union . ident . to_string () , kind : "union" . to_string () , content : item_union . to_token_stream () , }) , Item :: Use (item_use) => { let content = item_use . to_token_stream () . to_string () ; report . add_skipped_item ("use" . to_string () , "top-level use statements handled separately" . to_string () , & content) ; None } , Item :: Macro (item_macro) => { let macro_name = item_macro . mac . path . segments . last () . map_or ("unknown_macro" . to_string () , | s | s . ident . to_string ()) ; Some (ExtractedDecl { name : macro_name , kind : "macro" . to_string () , content : item_macro . to_token_stream () , metadata : ExtractedDeclMetadata :: default () , source_map : std :: collections :: HashMap :: new () , }) } , Item :: Mod (item_mod) => { let mod_name = item_mod . ident . to_string () ; Some (ExtractedDecl { name : mod_name , kind : "mod" . to_string () , content : item_mod . to_token_stream () , metadata : ExtractedDeclMetadata :: default () , source_map : std :: collections :: HashMap :: new () , }) } _ => { let content = item . to_token_stream () . to_string () ; println ! ("⚠️  Processing unsupported item type: {}" , content . chars () . take (100) . collect ::< String > ()) ; Some (ExtractedDecl { name : format ! ("unsupported_item_{}" , item_count) , kind : "generic" . to_string () , content : item . to_token_stream () , metadata : ExtractedDeclMetadata :: default () , source_map : std :: collections :: HashMap :: new () , }) } } ; if let Some (decl) = extracted_decl { let module_name_str = format ! ("{}_decls_{}" , paths . crate_name . replace ("-" , "_") , decl . name) ; let module_name_ident = Ident :: new (& module_name_str , Span :: call_site ()) ; collected_module_names . push (module_name_ident . clone ()) ; let decl_file_path = paths . decls_output_dir . join (format ! ("{}.rs" , module_name_str)) ; let custom_prelude = if let Some (ref prelude_str) = config . custom_prelude_overlay { prelude_str . parse :: < TokenStream > () . map_err (| e | anyhow :: anyhow ! ("Failed to parse custom prelude overlay: {}" , e)) ? } else { quote ! { } } ; let attributed_decl_content = quote ! { # [decl_ # module_name_ident] # decl . content } ; let file_content = quote ! { # custom_prelude # common_uses prelude ! { } # attributed_decl_content } ; if ! dry_run { let decl_file_path = paths . decls_output_dir . join (format ! ("{}.rs" , module_name_str)) ; let initial_content = add_generated_rust_header ! (file_content . to_string () . as_str () , file ! () , line ! ()) ; report . add_output_lines (count_lines_in_string (& initial_content)) ; match crate :: rustfmt_utils :: format_rust_file (& initial_content , & decl_file_path) { Ok (formatted_content) => { fs :: write (& decl_file_path , formatted_content) . context (format ! ("Failed to write formatted declaration to {}" , decl_file_path . display ())) ? ; } , Err (e) => { let error_comment = format ! ("// !!! Formatting failed for this module. The following code is unformatted. !!!\n\
                            // !!! Error: {} !!!\n\n" , e) ; let content_with_error_comment = error_comment + & initial_content ; fs :: write (& decl_file_path , content_with_error_comment) . context (format ! ("Failed to write unformatted declaration with error comment to {}" , decl_file_path . display ())) ? ; report . add_error_item (decl . kind . clone () , format ! ("Formatting failed: {}" , e) , & initial_content) ; error ! ("\n<blip style='color:red'>Formatting error for '{} {}' (written to {})</blip>" , decl . kind , decl . name , decl_file_path . display ()) ; } } println ! ("Split '{} {}' to {}" , decl . kind , decl . name , decl_file_path . display ()) ; } else { println ! ("Dry-run: Would split '{} {}' to {}" , decl . kind , decl . name , decl_file_path . display ()) ; } report . add_processed_item () ; } item_count += 1 ; } report . print_summary () ; Ok ((collected_module_names , report)) }
}